#!/usr/bin/env node
// Turns catalog/categories.json into three generated files:
//   hetzner/migrations/0002_seed_catalog.sql   the catalogue in the hetzner database
//   supabase/migrations/0009_catalogue.sql     the console's own read only copy
//   packages/shared/src/catalogue.ts           the list the screens and the API validate against
// Usage: node scripts/generate-catalog-seed.mjs
// Codes are derived mechanically from the labels, so nothing is invented: lowercase, ampersands dropped,
// every other run of non letters and digits becomes one underscore.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const src = JSON.parse(readFileSync(join(root, 'catalog/categories.json'), 'utf8'))

export const slug = (label) =>
  label.toLowerCase().replace(/&/g, ' ').normalize('NFKD').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')
const q = (s) => `'${s.replace(/'/g, "''")}'`

const catCodes = new Set()
const taskCodes = new Set()
let cats = ''
let tasks = ''
src.categories.forEach((c, ci) => {
  const code = slug(c.label)
  if (catCodes.has(code)) throw new Error(`Duplicate category code ${code}`)
  catCodes.add(code)
  cats += `  (${q(code)}, ${q(c.label)}, ${ci + 1}),\n`
  c.tasks.forEach((t, ti) => {
    const tcode = `${code}.${slug(t)}`
    if (taskCodes.has(tcode)) throw new Error(`Duplicate task type code ${tcode}`)
    taskCodes.add(tcode)
    tasks += `  (${q(tcode)}, ${q(code)}, ${q(t)}, ${ti + 1}),\n`
  })
})

const out = `-- 0002_seed_catalog.sql (hetzner)
-- GENERATED by scripts/generate-catalog-seed.mjs from catalog/categories.json. Do not edit by hand.
-- Seeds ${catCodes.size} service categories and ${taskCodes.size} task types, exactly as the live site lists them.
-- Nothing here is invented, renamed or merged. The console and the main backend can only read these tables.

begin;

insert into service_category (code, label, sort_order) values
${cats.replace(/,\n$/, '\n')}on conflict (code) do nothing;

insert into task_type (code, category_code, label, sort_order) values
${tasks.replace(/,\n$/, '\n')}on conflict (code) do nothing;

commit;
`
writeFileSync(join(root, 'hetzner/migrations/0002_seed_catalog.sql'), out)

// ---- the console's copy (Supabase) -------------------------------------------------------------------
const consoleSql = `-- 0009_catalogue.sql
-- GENERATED by scripts/generate-catalog-seed.mjs from catalog/categories.json. Do not edit by hand.
-- NOT APPLIED. Run after 0008.
--
-- The console's own copy of the service categories and task types (${catCodes.size} categories, ${taskCodes.size} task types, field
-- work only), the same codes as the hetzner database. Decision: the categories and task types never change from
-- the console. After the seed below, a trigger refuses every insert, update, delete and truncate on both tables,
-- for every role. A future change needs the owner's approval and a new migration that says so.

begin;

create table public.service_category (
  code       text primary key,
  label      text not null unique,
  sort_order int not null
);
create table public.task_type (
  code          text primary key,
  category_code text not null references public.service_category (code),
  label         text not null,
  sort_order    int not null,
  unique (category_code, label)
);

insert into public.service_category (code, label, sort_order) values
${cats.replace(/,\n$/, '\n')};

insert into public.task_type (code, category_code, label, sort_order) values
${tasks.replace(/,\n$/, '\n')};

create function public.catalogue_is_read_only() returns trigger
language plpgsql as $$
begin
  raise exception 'The service categories and task types cannot be changed from the console.';
end $$;

create trigger service_category_read_only before insert or update or delete on public.service_category for each row execute function public.catalogue_is_read_only();
create trigger task_type_read_only         before insert or update or delete on public.task_type         for each row execute function public.catalogue_is_read_only();
create trigger service_category_no_truncate before truncate on public.service_category for each statement execute function public.catalogue_is_read_only();
create trigger task_type_no_truncate        before truncate on public.task_type        for each statement execute function public.catalogue_is_read_only();

-- The standard conventions. Nothing can change these tables, so the audit and no delete triggers are
-- belt and braces, kept so the structural test that every table has them stays true.
create trigger service_category_audit     after insert or update on public.service_category for each row execute function public.audit_row_change('code');
create trigger task_type_audit            after insert or update on public.task_type        for each row execute function public.audit_row_change('code');
create trigger service_category_no_delete before delete on public.service_category for each row execute function public.block_hard_delete();
create trigger task_type_no_delete        before delete on public.task_type        for each row execute function public.block_hard_delete();

alter table public.service_category enable row level security;
alter table public.task_type        enable row level security;
create policy service_category_read on public.service_category for select to authenticated using (true);
create policy task_type_read        on public.task_type        for select to authenticated using (true);
revoke all on public.service_category, public.task_type from anon, authenticated;
grant select on public.service_category, public.task_type to authenticated;

commit;
`
writeFileSync(join(root, 'supabase/migrations/0009_catalogue.sql'), consoleSql)

const js = (v) => JSON.stringify(v).replace(/[^\x00-\x7f]/g, (ch) => `\\u${ch.charCodeAt(0).toString(16).padStart(4, '0')}`) // keep the source ASCII (one label has a dash)
// ---- the shared list -------------------------------------------------------------------------------
const tsCats = src.categories
  .map((c) => {
    const code = slug(c.label)
    const ts = c.tasks.map((t) => `{ code: ${js(`${code}.${slug(t)}`)}, label: ${js(t)} }`).join(', ')
    return `  { code: ${js(code)}, label: ${js(c.label)}, tasks: [${ts}] },`
  })
  .join('\n')
const ts = `// GENERATED by scripts/generate-catalog-seed.mjs from catalog/categories.json. Do not edit by hand.
// The ${catCodes.size} service categories and ${taskCodes.size} task types, exactly as the live site lists them. The console never adds, renames
// or removes one. Every category field in the console is chosen from this list and checked against it.

export type CatalogueTask = { code: string; label: string }
export type CatalogueCategory = { code: string; label: string; tasks: readonly CatalogueTask[] }

export const SERVICE_CATEGORIES: readonly CatalogueCategory[] = [
${tsCats}
]

export const CATEGORY_LABELS: readonly string[] = SERVICE_CATEGORIES.map((c) => c.label)
export const isCategoryLabel = (s: string): boolean => CATEGORY_LABELS.includes(s)
export const categoryByLabel = (label: string): CatalogueCategory | null => SERVICE_CATEGORIES.find((c) => c.label === label) ?? null
/** The task types of one category, chosen by the category's label (how the console stores it). */
export const taskTypesFor = (categoryLabel: string): readonly CatalogueTask[] => categoryByLabel(categoryLabel)?.tasks ?? []
export const taskTypeBelongsTo = (taskCode: string, categoryLabel: string): boolean => taskTypesFor(categoryLabel).some((t) => t.code === taskCode)
`
writeFileSync(join(root, 'packages/shared/src/catalogue.ts'), ts)
console.log(`categories ${catCodes.size}, task types ${taskCodes.size}`)
